const products = $('Load Products').all().map(i => i.json || {});
const outliers = $('Load Outliers').all().map(i => i.json || {});
const queueRows = $('Load Video Queue').all().map(i => i.json || {});

// Automatically pick the next approved product in tts_products that hasn't been queued recently, or rotate through approved products!
const approvedProducts = products.filter(p => p.status === 'approved');
const usedProductKeys = new Set(queueRows.map(q => q.product_key));
const nextUnused = approvedProducts.find(p => !usedProductKeys.has(p.product_key));
const prodObj = nextUnused || approvedProducts[queueRows.length % Math.max(1, approvedProducts.length)] || {
  product_key: 'prod_7in1_tech_cleaner',
  product_name: '7-in-1 / 8-in-1 Pro Elektronik, Tastatur & AirPods Reinigungs-Set',
  category: 'tech_desk_gadgets',
  problem_solved: 'Verstopfte AirPods-Lautsprechergitter (leiser Ton), Staub zwischen mechanischen Tastatur-Tasten und Fingerabdrücke auf dem Smartphone-Display.',
  key_specs: 'Faltbarer Dual-Head Reinigungs-Pen mit Metallspitze, hochdichter Mikro-Bürste & weichem Beflockungs-Schwämmchen für das Ladecase, ausfahrbare Tastatur-Bürste, Keycap-Puller (Tastenzieher), integriertes Display-Reinigungsspray und abnehmbares Super-Mikrofaser-Pad.'
};

const productKey = prodObj.product_key;
const matchedOutlier = outliers.find(o => o.matched_product_key === productKey) || outliers[0] || {};
const outlierKey = matchedOutlier.outlier_key || ('outlier_' + productKey);
const videoKey = 'vid_hf1to1_' + productKey.replace('prod_', '') + '_' + Date.now().toString().slice(-5);

// Select Avatar & Voice automatically based on category (Tech/Gadgets/Car/SmartHome -> Jonas | Beauty/Style/Health -> Mia)
const isBeauty = /beauty|skin|style|health|medicube|collagen/i.test(String(prodObj.category || '') + ' ' + productKey);
const avatarKey = isBeauty ? 'avatar_sarah_smartliving_de' : 'avatar_lukas_tech_de';

const refVideoUrl = matchedOutlier.source_video_stream_url || 'https://api.apify.com/v2/key-value-stores/U23LDAN9oAsYpdj76/records/video-luxcleante-20260218135021-7608202200036199702.mp4?signature=Gun2w3RFo2IqgWdWzf7o';

const scenes = [
  {
    scene_no: 1,
    role: 'hook',
    ref_timestamp: '00:00:05.0',
    duration_sec: 4.5,
    spoken_text: 'Wann hast du das letzte Mal deine AirPods und deine Tastatur richtig gereinigt?',
    overlay_badge: 'SCHLUSS MIT SCHMUTZ',
    edit_prompt: 'Keep the exact same close-up hand holding the product in vertical 9:16 portrait frame, photorealistic, no text overlays.',
    motion_prompt: 'smooth close-up product demonstration of ' + prodObj.product_name
  },
  {
    scene_no: 2,
    role: 'hero_reveal',
    ref_timestamp: '00:00:08.5',
    duration_sec: 4.5,
    spoken_text: 'Dieses kompakte sieben in eins Set hat fuer jede Ritze das perfekte Werkzeug.',
    overlay_badge: '7-IN-1 REINIGUNGS-SET',
    edit_prompt: 'Keep the exact same two hands opening the product cap in vertical 9:16 frame, photorealistic, no text overlays.',
    motion_prompt: 'hands demonstrating ' + prodObj.product_name
  },
  {
    scene_no: 3,
    role: 'hero_reveal',
    ref_timestamp: '00:00:15.5',
    duration_sec: 4.5,
    spoken_text: 'Mit der ausfahrbaren Buerste und dem Tastenzieher wird deine Tastatur bis unter die Tasten sauber.',
    overlay_badge: 'TASTATUR & KEYCAP-PULLER',
    edit_prompt: 'Keep the exact same close-up of the brush sweeping dust from between the mechanical keyboard switches on the desk.',
    motion_prompt: 'cleaning brush sweeping dust between mechanical keyboard switches'
  },
  {
    scene_no: 4,
    role: 'hero_reveal',
    ref_timestamp: '00:00:03.2',
    duration_sec: 4.5,
    spoken_text: 'Und mit dem integrierten Display-Spray und Mikrofaser-Pad verschwinden alle Fingerabdruecke vom Handy.',
    overlay_badge: 'DISPLAY-SPRAY & PAD',
    edit_prompt: 'Keep the exact same hands wiping a black smartphone screen clean using the microfiber pad side of the cleaner kit.',
    motion_prompt: 'hand wiping smartphone screen clean with the microfiber side of the cleaner'
  },
  {
    scene_no: 5,
    role: 'hero_reveal',
    ref_timestamp: '00:00:12.0',
    duration_sec: 4.5,
    spoken_text: 'Im Inneren steckt der faltbare Reinigungs-Stift speziell fuer deine Kopfhoerer.',
    overlay_badge: 'FALTBARER AIRPODS-STIFT',
    edit_prompt: 'Keep the exact same close-up of a hand holding the white foldable dual-head AirPods cleaning pen against the desk background.',
    motion_prompt: 'hand showing the compact white foldable earbuds cleaning pen'
  },
  {
    scene_no: 6,
    role: 'hero_reveal',
    ref_timestamp: '00:00:19.0',
    duration_sec: 4.5,
    spoken_text: 'Die feine Spitze und die Mikro-Buerste loesen selbst festsitzenden Schmutz am Lautsprechergitter.',
    overlay_badge: 'METALLSPITZE & MIKRO-BUERSTE',
    edit_prompt: 'Keep the exact same close-up of hands unfolding the precision cleaning tip and high-density mini brush on the white AirPods cleaning pen.',
    motion_prompt: 'fingers unfolding the precision tip and mini brush of the earbuds cleaning pen'
  },
  {
    scene_no: 7,
    role: 'hero_reveal',
    ref_timestamp: '00:00:22.5',
    duration_sec: 4.5,
    spoken_text: 'Und das weiche Beflockungs-Schwaemmchen reinigt das tiefe AirPods-Ladecase in Sekunden.',
    overlay_badge: 'SAUBERES LADECASE',
    edit_prompt: 'Keep the exact same close-up of the white flocking sponge tip cleaning deep inside the white AirPods charging case.',
    motion_prompt: 'soft flocking sponge cleaning deep inside the white earbuds charging case'
  },
  {
    scene_no: 8,
    role: 'cta',
    ref_timestamp: '00:00:26.0',
    duration_sec: 6.5,
    spoken_text: 'So klingen deine Kopfhoerer sofort wieder wie neu! Ich hab dir das sieben in eins Set unten links im orangenen Warenkorb verlinkt – sicher es dir jetzt!',
    overlay_badge: 'UNTEN LINKS IM WARENKORB',
    edit_prompt: 'Keep the exact same close-up of the precision tip and mini brush cleaning the speaker mesh of a white wireless earbud.',
    motion_prompt: 'precision cleaning pen brushing the speaker mesh of a white wireless earbud'
  }
];

const fullScript = scenes.slice(0, 3).map(s => s.spoken_text).join(' ') + ' ||| ' + scenes.slice(3, 6).map(s => s.spoken_text).join(' ') + ' ||| ' + scenes.slice(6).map(s => s.spoken_text).join(' ');

// Generate SEO-optimized German TikTok Shop description & hashtag block from the original product description via Hugging Face Inference LLM!
const TOKEN = $env.HF_TOKEN || '';
let seoCaptionDe = prodObj.product_name + ' – ' + prodObj.problem_solved + '\n• ' + prodObj.key_specs + '\nDirekt unten links im orangenen Warenkorb verlinkt! #tiktokshopde #tiktokmademebuyit #bizpunk72';

if (TOKEN) {
  try {
    const llmResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://router.huggingface.co/v1/chat/completions',
      headers: {
        Authorization: 'Bearer ' + TOKEN,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: 'Qwen/Qwen2.5-72B-Instruct',
        temperature: 0.3,
        max_tokens: 450,
        messages: [
          {
            role: 'system',
            content: 'Du bist ein TikTok-Search-SEO-Experte für TikTok Shop Deutschland (@bizpunk72). Erstelle aus der Original-Produktbeschreibung eine verkaufsstarke, SEO-optimierte deutsche TikTok-Beschreibung mit: 1. Search-Hook in Zeile 1, 2. 4 Bulletpoints (•) mit den exakten Funktionen aus der Original-Produktbeschreibung, 3. Hinweis auf den orangenen Warenkorb unten links, 4. Zeile "Suchbegriffe: ..." mit 5 deutschen Long-Tail-Keywords, 5. 10 relevanten Hashtags inkl. #tiktokshopde #tiktokmademebuyit #bizpunk72. Gib NUR den fertigen Beschreibungstext ohne Einleitung aus.'
          },
          {
            role: 'user',
            content: 'Produkt: ' + prodObj.product_name + '\nGelöstes Problem: ' + prodObj.problem_solved + '\nOriginal-Produktbeschreibung / Specs: ' + prodObj.key_specs
          }
        ]
      }),
      timeout: 25000
    });
    const genText = llmResp?.choices?.[0]?.message?.content?.trim();
    if (genText && genText.length > 120) {
      seoCaptionDe = genText;
    }
  } catch (e) {}
}

return [{
  json: {
    video_key: videoKey,
    product_key: productKey,
    outlier_key: outlierKey,
    avatar_key: avatarKey,
    cta_mode: 'tiktok_shop_cart',
    hook_de: scenes[0].spoken_text,
    caption_de: seoCaptionDe,
    script_de_full: fullScript,
    scenes_json: JSON.stringify(scenes),
    approval_status: 'approved',
    render_status: 'queued',
    final_video_url: refVideoUrl,
    created_at: new Date().toISOString()
  }
}];
